pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address from, uint256 v, uint8 decimals, address tos0) public {
        vm.assume(tos0 != address(0));
        v = bound(v, 1, type(uint256).max / 2);
        decimals = uint8(bound(decimals, 0, 18));

        Reverter rev = new Reverter();

        address[] memory tos = new address[](1);
        tos[0] = tos0;

        bool okRef;
        try c.transfer(from, address(rev), tos, v, decimals) {
            okRef = true;
        } catch {
            okRef = false;
        }

        assertTrue(okRef == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
